\sum_{p \in P_{N^{1/2}}} \frac{1}{p} \sum_{\alpha \in \mathbb{Z}_p^*}  \left| \widehat{\pi_p 1_X} (\alpha) \right|^2   \lesssim N^{1/2} |X|, \tag{4}
